-- Second Chinese article translations batch (deepening phase, final
-- language of this round). Same 3 additional articles as the earlier
-- batch 2s: Things to do in Maldives, Most Famous Places In The World,
-- and the Maldives Honeymoon guide. entity_id resolved via scalar
-- subquery on the canonical English slug (see the entity_id fix commit
-- for why this matters).
insert into translations (entity_id, entity_type, locale, slug, title, short_description, description, body_html, meta_title, meta_description, translation_status, translated_by) values
  ((select id from nodes where node_type = 'article' and slug = 'things-to-do-in-maldives'), 'article', 'zh', 'maldives-keyi-zuo-de-shiqing', '马尔代夫可以做的事情', '假期期间在马尔代夫可以体验的12项最佳活动。这些活动大多在所有度假村都可以参加。', null, '<h3>浮潜</h3><p>马尔代夫拥有世界上最壮观的浮潜体验之一。这得益于该地区丰富的珊瑚礁资源以及极为清澈的海水。事实上，这里有近70种不同的珊瑚礁，以及700多种海洋生物。这意味着，在这里浮潜时，您一定会看到令人惊叹的多样化动植物。您可能看到的物种包括礁鲨、各种海龟、鳐鱼、苏眉鱼和海鳝。无论您是否熟悉海洋生物，都能欣赏到您所观察到的五彩斑斓的生物多样性。浮潜是马尔代夫极力推荐的活动之一。</p><figure><img src="legacy/images/articles/snorkeling.webp" alt="maldives" loading="lazy" /></figure><h3>潜水</h3><p>由于拥有白色沙滩、珊瑚礁、清澈温暖的海水、众多潜水点和丰富的海洋生物，马尔代夫已成为世界上最好的潜水目的地之一。</p><p>马尔代夫大多数度假村都设有潜水设施，并有众多潜水游艇运营商提供潜水假期，带领游客前往马尔代夫各地的众多潜水点。许多潜水者渴望在马尔代夫潜水，是因为这里有鲸鲨、蝠鲨、鹰鳐、礁鲨、锤头鲨和海鳝，以及许多较小的鱼类和珊瑚物种。潜水是马尔代夫最佳的活动之一。</p><figure><img src="legacy/images/articles/maldives-diving.webp" alt="maldives" loading="lazy" /></figure><h3>钓鱼</h3><p>马尔代夫以其世界顶级的大型海钓目的地著称，这里生活着丰富的远洋鱼类，如金枪鱼、鲯鳅、鲅鱼、梭鱼和剑鱼。马尔代夫有严格的渔业法规，这些法规得到广泛执行，以维持渔业资源供当地居民赖以生存。</p><figure><img src="legacy/images/articles/fishing.webp" alt="maldives" loading="lazy" /></figure><h3>海滩</h3><p>马尔代夫的海滩以其洁白和清澈的水质而闻名。在马尔代夫的一些地区，海滩在夜间会发光，这是由海洋浮游生物引起的现象。<a href="/maldives/islands/fuvahmulah/">福瓦穆拉</a>的海滩以其闪光的石头而闻名。</p><figure><img src="legacy/images/articles/maldives-sand-bank.webp" alt="maldives" loading="lazy" /></figure><h3>瑜伽</h3><p>瑜伽是一组起源于古印度的身体、心理和精神修行方法。瑜伽是印度哲学传统中六大正统学派之一。马尔代夫的度假村提供各种瑜伽课程，最佳练习时间是日出和日落时分。</p><h3>水疗</h3><p>马尔代夫几乎所有的度假村都提供多种身体按摩服务。许多国际知名的水疗品牌也在马尔代夫设有分店。</p><h3>水下用餐</h3><p>马尔代夫拥有世界上第一家水下餐厅。目前共有6家水下餐厅分布在不同地区。这些建在海面以下数米处的餐厅，通过玻璃天花板提供壮观的海洋生物景观，彻底重新定义了马尔代夫水下用餐的体验。</p><h3>岛屿漫游</h3><p>岛屿漫游是发现马尔代夫当地文化和历史的最佳方式。马尔代夫各地共有200个本地岛屿，几乎所有度假村和酒店都为游客提供参观这些本地岛屿的游览项目。</p><p>马累市是马尔代夫的首都，拥有许多重要而有趣的景点。如果您住在度假村，参观首都最好的方式是在离境当天：提前抵达马累国际机场，再从机场乘坐10分钟的车程前往市区。如果您在马累机场有等待时间，这是最值得做的事情之一。</p><figure><img src="legacy/images/articles/day-tours-to-villages.webp" alt="maldives" loading="lazy" /></figure><h3>观鲸潜艇</h3><p>观鲸潜艇是不会游泳或不能潜水的人的最佳选择。马尔代夫的海洋生物是这个国家最丰富的财富。如果您因任何原因无法潜水或下水，不必担心——马尔代夫提供观鲸潜艇游览项目。</p><h3>冲浪</h3><p>马尔代夫的冲浪受到东北季风和西南季风的影响。在东北季风期间（3月至4月），南部环礁的条件最为理想。5月至10月的西南季风期间，最佳的冲浪区域则在北部或中部环礁。</p><h3>马尔代夫购物</h3><p>纪念品购物在马尔代夫游客中非常受欢迎，纪念品商店出售当地制造的商品、珊瑚、贝壳以及许多手工制品。马累市是购买纪念品最引人注目的地方，也可以在线购物并配送。</p><figure><img src="legacy/images/articles/maldives-shopping.webp" alt="maldives" loading="lazy" /></figure><h3>游览与水上运动</h3><p>马尔代夫还提供许多其他类型的游览项目和水上运动。以下是一些最常见的游览项目。</p><p>蝠鲨观赏 观鲸 观赏海豚 喂鲨鱼 喂鳐鱼 日落巡游 日出巡游 赤道之旅</p><p>摩托艇 香蕉船 划皮划艇 风帆冲浪 滑翔伞 水上滑雪 双体船巡游</p><figure><img src="legacy/images/articles/dolphin-cruise.webp" alt="maldives" loading="lazy" /></figure>', '马尔代夫可以做的事情 | 马尔代夫旅行指南 | MTG', '假期期间在马尔代夫可以体验的12项最佳活动。这些活动大多在所有度假村都可以参加。', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'most-famous-places-in-the-world'), 'article', 'zh', 'shijie-shang-zui-zhuming-de-difang', '世界上最著名的地方', '面向游客的世界最著名地点和目的地清单，附带趣闻事实。', null, '<p>作者：Shayad Saeed</p><p>日期：2021年2月2日</p><p>世界上有数百个著名的地方，根据我的研究，我将重点介绍其中最知名的10个。地标赋予我们一种地方感。这些历史遗迹和自然奇观将我们与某个地方联系在一起，并激发我们前去参观的欲望。埃菲尔铁塔位于巴黎，自由女神像位于纽约市。这10个景点，对各自所在地和历史都具有重要意义，应该列入您的旅行愿望清单。</p><figure><img src="legacy/images/articles/ar/famous-places-in-the-world.webp" alt="famous places in the world" loading="lazy" /></figure><h4>哈利法塔，迪拜</h4><p>在阿拉伯联合酋长国的迪拜，哈利法塔是一座摩天大楼。自2009年以来，它一直是世界上最高的结构和建筑，总高度为829.8米（略超半英里），超过了此前的纪录保持者台北101大楼。以下是与哈利法塔相关的记录：</p><p>这些记录使其成为世界上最佳的地方之一。</p><figure><img src="legacy/images/articles/ar/famous-places-on-the-world.webp" alt="famous places on the world" loading="lazy" /></figure><h4>埃菲尔铁塔，法国</h4><p>埃菲尔铁塔，法语中也称为La Tour Eiffel，是1889年巴黎世博会的中心建筑。它的建造是为了纪念法国大革命一百周年，并向世界展示法国的工业实力。后来，由于以下原因，它成为了这座城市的象征：</p><figure><img src="legacy/images/articles/ar/most-famous-places-in-the-world.webp" alt="most famous places in the world" loading="lazy" /></figure><h4>悉尼歌剧院</h4><p>悉尼歌剧院是位于澳大利亚新南威尔士州悉尼悉尼港的多场馆表演艺术中心。它是二十世纪最著名、最具特色的建筑之一。</p><figure><img src="legacy/images/articles/ar/famous-destinations-in-the-world.webp" alt="famous destinations in the world" loading="lazy" /></figure><h4>自由女神像：纽约</h4><p>自由女神像是美国最著名的地标之一，位于纽约港。这座纪念碑由法国人民于1886年建造，象征两国之间的友谊，并于1924年被指定为国家纪念碑。游客可以从下曼哈顿的炮台公园乘坐渡轮抵达，该渡轮同时停靠埃利斯岛和自由岛。</p><figure><img src="legacy/images/articles/ar/best-places-in-the-world.webp" alt="best places in the world" loading="lazy" /></figure><h4>吉萨大金字塔：埃及开罗</h4><p>吉萨大金字塔及其周边的金字塔群已有超过4000年的历史。它们位于开罗郊外，沿尼罗河而建。这些由胡夫王约于公元前2500年建造的古代遗迹，也是古代世界七大奇迹之一——并且是唯一至今仍存的一个。</p><figure><img src="legacy/images/articles/ar/famous-destinations.webp" alt="famous destinations" loading="lazy" /></figure><h4>新加坡滨海湾金沙</h4><p>滨海湾金沙是新加坡中央商务区的一家酒店兼购物区。2010年开业时，它被宣传为世界上最昂贵的独立赌场物业，包括土地成本共耗资80亿新加坡元（合68.8亿美元）。</p><figure><img src="legacy/images/articles/ar/famous-places.webp" alt="famous places" loading="lazy" /></figure><h4>泰姬陵：印度阿格拉</h4><p>泰姬陵是为皇帝沙贾汗的妻子而建造的。联合国教科文组织将这座于1648年完工的建筑指定为印度-伊斯兰建筑的最佳范例。泰姬陵位于阿格拉市，从首都新德里乘坐一小时飞机或三小时火车即可到达。由于这个景点人流量巨大，最好在工作日前往参观。日出时，白色大理石建筑会被洒上迷人的光辉。</p><figure><img src="legacy/images/articles/ar/famous-places-to-visit-in-the-world.webp" alt="famous places to visit in the world" loading="lazy" /></figure><h4>马尔代夫群岛</h4><p>马尔代夫是位于印度洋的由1200个岛屿组成的岛链。马尔代夫以其独特性和自然美景而闻名。由于其地理位置，最佳游览时间是10月至5月之间。基于以下原因，它被认为是世界上最值得游览的地方之一：</p><figure><img src="legacy/images/articles/ar/best-places-to-tavel-in-the-world.webp" alt="best places to tavel in the world" loading="lazy" /></figure><h4>波拉波拉岛</h4><p>波拉波拉岛是波利尼西亚附近的一个小岛（长约10公里，宽略超3公里）。岛的中心有一座休眠火山，向外延伸为茂密的丛林，最终汇入一片碧绿色的潟湖。这些特点使其成为最佳旅行目的地之一：</p><figure><img src="legacy/images/articles/ar/famous-places-to-travel-in-the-world.webp" alt="famous places to-travel in the world" loading="lazy" /></figure><h4>南岛，新西兰</h4><p>新西兰南岛处处都充满壮丽的风景，是联合国教科文组织世界遗产地区。以下事实使其成为最著名的旅行目的地之一。</p>', '世界上最著名的地方 | 马尔代夫旅行指南 | MTG', '面向游客的世界最著名地点和目的地清单，附带趣闻事实。', 'published', 'claude'),
  ((select id from nodes where node_type = 'article' and slug = 'maldives-honeymoon-ultimate-romantic-getaway-guide'), 'article', 'zh', 'maldives-miyue-zhongji-langman-zhinan', '马尔代夫蜜月：终极浪漫假期指南', '完整的马尔代夫蜜月指南——发现最佳的浪漫度假村、水上别墅、套餐以及为您打造完美天堂情侣之旅的独特体验。', null, '<figure><img src="legacy/images/maldives-honeymoons.webp" alt="Romantic Maldives honeymoon couple on beach" loading="lazy" /></figure><p>马尔代夫无可争议地是蜜月旅行者的天堂，为新婚夫妇提供自然美景、隐私和浪漫的绝佳结合。这个由1192个珊瑚岛组成、散布在印度洋上的群岛，已将情侣度假的艺术发挥到极致，其度假村专为创造难忘的浪漫体验而设计。</p><p>马尔代夫与其他热带目的地的不同之处在于其独特的地理环境——每个度假村通常都拥有自己独立的私人岛屿，确保了完全的隐蔽性。马尔代夫开创的标志性水上别墅，让情侣们可以在别墅下方海浪轻柔拍打的声音中醒来，并直接步入清澈的潟湖中。</p><p>除了自然的美丽之外，马尔代夫的度假村还专注于打造个性化的浪漫体验。从沙洲上的私人野餐到被海洋生物环绕的水下餐厅，创造特别时刻的机会无穷无尽。该国的穆斯林文化意味着公开的亲密表达仅限于度假村岛屿，营造出一种含蓄而私密的氛围，非常适合度蜜月的情侣。</p><h2>为什么马尔代夫是终极蜜月目的地</h2><figure><img src="legacy/images/activities/virgin-islands-excursion.webp" alt="Private island in Maldives" loading="lazy" /></figure><p>几个关键因素使马尔代夫成为世界领先的蜜月目的地：</p><h4>1. 无与匹敌的隐私</h4><p>与拥挤的海滩目的地不同，马尔代夫的度假村提供真正的隔离体验。大多数度假村占据私人岛屿，仅有50到150间别墅，这意味着您常常能独享整片海滩。度假村岛屿经过精心设计，以最大限度地保护隐私，住宿之间设有植被缓冲区。</p><h4>2. 水上别墅体验</h4><p>马尔代夫发明了豪华水上别墅的概念。现代版本配有玻璃地板面板、私人无边泳池和直达潟湖的通道。阅读我们关于马尔代夫水上别墅的完整指南，了解如何选择完美的别墅。</p><h4>3. 全包式浪漫</h4><p>度假村专注于提供无忧的浪漫体验。管家可以安排一切，从惊喜求婚到纪念日庆典。大多数度假村提供包含浪漫福利的特别蜜月套餐。</p><h4>4. 全年温暖的天气</h4><p>全年平均气温为28至30摄氏度，水温约为27摄氏度，马尔代夫始终是蜜月的理想之地。尽管有雨季，但降雨通常短暂。</p><h4>5. 无与媲美的海洋生物</h4><p>马尔代夫的珊瑚环礁为多样化的海洋生物创造了完美的条件。许多度假村拥有出色的自有珊瑚礁，游客可以直接从自己的别墅出发，与海龟、鳐鱼和热带鱼一起浮潜。</p><h2>马尔代夫蜜月最佳5大度假村</h2><figure><img src="legacy/resorts/four-seasons-huraa/images/four-seasons-maldives-at-kuda-huraa-sunset-water-bangalow1.webp" alt="Four Seasons Kuda Huraa overwater bungalow" loading="lazy" /></figure><h3>1. Four Seasons Resort Maldives at Kuda Huraa</h3><p>这家传奇度假村为马尔代夫蜜月设立了标杆，提供：</p><ul><li>最近翻新的水上别墅，提供全天候管家服务</li><li>高级别墅内设私人无边泳池</li><li>世界知名的水疗中心，设有水上理疗室</li><li>七家餐厅，包括礁边海鲜烤肉餐厅</li><li>根据季节提供免费的鲸鲨观赏之旅</li></ul><p>蜜月套餐：包含香槟、情侣按摩、私人日落巡游和浪漫晚餐（最短入住5晚）</p><p>最适合：追求完美服务和奢华体验的情侣</p><figure><img src="legacy/resorts/baros-island/images/baros-maldives-island-resort-beach-dinner.webp" alt="Baros Maldives beach dinner" loading="lazy" /></figure><h3>2. Baros Maldives</h3><p>这家私密的精品度假村非常适合追求隐私的情侣：</p><ul><li>小型私人岛屿上仅有75间别墅</li><li>别墅坐落于茂密植被之中，确保最大隐私</li><li>可从海滩直达的出色自有珊瑚礁</li><li>标志性的灯塔餐厅坐落于潟湖之上</li><li>个性化的浪漫体验</li></ul><p>蜜月套餐：包含香槟、水果篮、60分钟水疗护理和私人晚餐（最短入住4晚）</p><p>最适合：重视亲密感和自然美景的情侣</p><h2>马尔代夫蜜月套餐详解</h2><figure><img src="legacy/images/romantic-sunrise-breakfast.webp" alt="Romantic breakfast in Maldives" loading="lazy" /></figure><p>几乎所有马尔代夫度假村都提供特别的蜜月套餐。这些套餐通常要求提供过去6至12个月内的结婚证明。主要内容包括：</p><h4>标准内容：</h4><ul><li>欢迎香槟和水果篮</li><li>浪漫的床铺装饰</li><li>情侣按摩（通常为30至60分钟）</li><li>特别的蜜月蛋糕或甜点</li><li>纪念证书或礼物</li></ul><h4>高级附加项目：</h4><ul><li>私人日落巡游</li><li>星空下的海滩晚餐</li><li>保证的别墅升级</li><li>专业摄影师拍摄服务</li><li>个性化游览，如私人游艇租赁</li></ul><h2>难忘的浪漫体验</h2><figure><img src="legacy/images/articles/ozen-maadhoo-underwater-restaurant.webp" alt="Underwater restaurant Maldives" loading="lazy" /></figure><h4>1. 水下用餐</h4><p>几家度假村设有令人惊叹的水下餐厅，在这里用餐时可以被海洋生物环绕。最著名的是Conrad马尔代夫的Ithaa餐厅，这是世界上第一家全玻璃水下餐厅。</p><figure><img src="legacy/images/stargazing-on-the-maldives-beach.webp" alt="Stargazing in Maldives" loading="lazy" /></figure><h4>2. 私人观星</h4><p>由于光污染极小，马尔代夫拥有壮观的夜空。一些度假村提供望远镜，并配有天文学家为您讲解星座，同时您可以在私人露台上放松身心。</p>', '马尔代夫蜜月：终极浪漫假期指南 | 马尔代夫旅行指南 | MTG', '完整的马尔代夫蜜月指南——发现最佳的浪漫度假村、水上别墅、套餐以及为您打造完美天堂情侣之旅的独特体验。', 'published', 'claude')
